"""Route-based interlocking logic for a small tram junction.

A *route* is a predefined path through the junction from an entry
signal to an exit signal. Before a route can be set (and its entry
signal cleared to a proceed aspect), the interlocking must confirm:

* every track circuit the route passes over is clear,
* every point on the route can be set to the position the route needs,
* no conflicting route is currently locked.

This mirrors, in miniature, the route-locking principle used on real
tramway and railway interlockings: only one of a set of conflicting
movements may be locked at a time, and a locked point may not be
thrown until the route that locked it is released.
"""

from dataclasses import dataclass, field
from typing import Dict, List, Set

from track_model import Point, TrackCircuit


@dataclass
class Route:
    route_id: str
    entry_signal: str
    exit_signal: str
    track_circuit_ids: List[str]
    point_positions: Dict[str, str]  # point_id -> required position
    conflicts: Set[str] = field(default_factory=set)


class RouteRequestError(Exception):
    """Raised when a route cannot be safely set."""


class Interlocking:
    """Holds the current locking state of every route through a junction."""

    def __init__(
        self,
        track_circuits: Dict[str, TrackCircuit],
        points: Dict[str, Point],
        routes: Dict[str, Route],
    ):
        self.track_circuits = track_circuits
        self.points = points
        self.routes = routes
        self._locked_routes: Set[str] = set()

    def is_locked(self, route_id: str) -> bool:
        return route_id in self._locked_routes

    def locked_routes(self) -> Set[str]:
        return set(self._locked_routes)

    def _conflicting_locked_route(self, route: Route) -> str:
        for other_id in self._locked_routes:
            if other_id in route.conflicts:
                return other_id
        return ""

    def request_route(self, route_id: str) -> None:
        """Attempt to set and lock a route.

        Raises RouteRequestError if the route cannot be safely set.
        On success, every point on the route is thrown to the
        position the route requires and locked there, and the route
        itself is marked locked.
        """
        if route_id not in self.routes:
            raise RouteRequestError(f"no such route {route_id!r}")
        route = self.routes[route_id]

        if route_id in self._locked_routes:
            return  # already set; re-requesting the same route is a no-op

        blocking = self._conflicting_locked_route(route)
        if blocking:
            raise RouteRequestError(
                f"route {route_id} conflicts with locked route {blocking}"
            )

        for tc_id in route.track_circuit_ids:
            if self.track_circuits[tc_id].occupied:
                raise RouteRequestError(
                    f"route {route_id} blocked: track circuit {tc_id} occupied"
                )

        for point_id, required in route.point_positions.items():
            point = self.points[point_id]
            if point.locked:
                # The conflict table above is maintained by hand when routes
                # are commissioned. If two routes that share a point were
                # ever left out of each other's conflict set by mistake,
                # this is the check that stops them being locked together.
                raise RouteRequestError(
                    f"point {point_id} is locked by another route"
                )
            if point.position != required and point.blade_circuit.occupied:
                raise RouteRequestError(
                    f"point {point_id} cannot be thrown: blades occupied"
                )

        # All checks passed -- commit the route.
        for point_id, required in route.point_positions.items():
            point = self.points[point_id]
            if point.position != required:
                point.throw(required)
            point.locked = True

        self._locked_routes.add(route_id)

    def release_route(self, route_id: str) -> None:
        """Release a locked route, unlocking its points.

        Should only be called once the tram has fully cleared every
        track circuit on the route -- callers can confirm this with
        :meth:`route_is_fully_clear` first.
        """
        if route_id not in self._locked_routes:
            return
        route = self.routes[route_id]
        for point_id in route.point_positions:
            self.points[point_id].locked = False
        self._locked_routes.discard(route_id)

    def route_is_fully_clear(self, route_id: str) -> bool:
        """True if every track circuit on the route is unoccupied."""
        route = self.routes[route_id]
        return all(
            not self.track_circuits[tc_id].occupied
            for tc_id in route.track_circuit_ids
        )
